/**
 * 高精度搜索和语义查询引擎
 */
导出异步函数 searchSentences(
  查询：字符串，
  过滤器：SearchFilterOptions = {}
): Promise<{ 结果: SentenceItem[];总数：数量； SemanticMatches?: SemanticExplanationMatch[] }> {
  const all = 等待 loadSentences();
  常量规范化查询=规范化文本（查询）；
  const queryTokens = 标准化查询 ? NormalizedQuery.split(' ').filter(Boolean) : [];

  常量{
    cefr = '全部',
    部分=“全部”，
    类别=“全部”，
    子类别 = '全部',
    语法 = '全部',
    形式=“全部”，
    限制= 50，
    偏移量=0，
  } = 过滤器；

  // 过滤传递
  让过滤= all.filter(s => {
    if (cefr !== 'all' && s.cefr !== cefr) 返回 false;
    if (section !== 'all' && s.section !==section) return false;
    if (category !== 'all' && s.category !== 类别) return false;
    if (subcategory !== 'all' && s.subcategory !== subcategory) return false;
    if (grammar !== 'all' && !s.grammar.toLowerCase().includes(grammar.toLowerCase())) 返回 false;
    if (formality!== 'all' && s.formality.toLowerCase() !==formality.toLowerCase()) return false;
    返回真；
  });

  if (!normalizedQuery) {
    const 总计 = 过滤后的长度；
    const 分页 = 已过滤。切片（偏移量，偏移量+限制）；
    返回{结果：分页，总计}；
  }

  // 评分算法
  接口ScoredItem {
    项目：句子项目；
    分数：数字；
    方面：SemanticExplanationMatch['matchedAspect'];
  }

  常量得分：ScoredItem[] = []；

  for (const s of 已过滤) {
    让分数= 0；
    让 matchesAspect: SemanticExplanationMatch['matchedAspect'] = 'english';

    constnormEn=normalizeText(s.english);
    constnormEg=normalizeText(s.arabicEg);
    constnormFusha=normalizeText(s.arabicFusha);
    constnormGrammar=normalizeText(s.grammar);
    const NormPurpose = NormalizeText(s.Purpose);

    // 完全句子匹配
    if (normEn === 规范化查询) {
      分数+=100；
      matchedAspect = '英语';
    } else if (normEg === 规范化查询) {
      分数+= 95；
      matchedAspect = '阿拉伯语-eg';
    } else if (normFusha === normalizedQuery) {
      分数+= 90；
      matchedAspect = '阿拉伯语-fusha';
    }

    //子串包含
    if (normEn.includes(normalizedQuery)) {
      分数+= 50；
      matchedAspect = '英语';
    } else if (normEg.includes(normalizedQuery)) {
      分数+= 45；
      matchedAspect = '阿拉伯语-eg';
    } else if (normFusha.includes(normalizedQuery)) {
      分数+= 40；
      matchedAspect = '阿拉伯语-fusha';
    } else if (normGrammar.includes(normalizedQuery)) {
      分数+= 35；
      matchedAspect = '语法';
    } else if (normPurpose.includes(normalizedQuery)) {
      分数+= 30；
      matchedAspect = '概念';
    }

    // 令牌匹配
    让 tokenMatches = 0;
    for (queryTokens 的 const 标记) {
      if (normEn.includes(token)) tokenMatches += 5;
      if (normEg.includes(token)) tokenMatches += 4;
      if (normFusha.includes(token)) tokenMatches += 3;
      if (s.vocabulary.some(v => normalizeText(v).includes(token))) tokenMatches += 4;
      if (s.tags.some(t => normalizeText(t).includes(token))) tokenMatches += 3;
    }
    分数+= tokenMatches；

    如果（分数> 0）{
      Scored.push({ 项目: s, 分数, 方面:matchedAspect });
    }
  }

  Scored.sort((a, b) => b.score - a.score);

  // 语义解释匹配顶级项目
  const SemanticMatches: SemanticExplanationMatch[] = Scored.slice(0, 5).map(s => {
    让细微差别=''；
    if (s.item.grammar.toLowerCase().includes('过去连续')) {
      nuance = '过去进行时表明事件在过去的特定时间点正在进行。';
    } else if (s.item.grammar.toLowerCase().includes('现在完成连续')) {
      nuance = '现在完成进行时强调过去的时间并持续到说话的那一刻。';
    } else if (s.item.grammar.toLowerCase().includes('未来完美')) {
      nuance = '将来完成时表示某件事将在未来的某个特定时间之前完成。';
    } else if (s.item.grammar.toLowerCase().includes('indirect')) {
      nuance = '间接请求的形式是英语交流中外交礼仪的顶峰。';
    }
    返回{
      句子：s.item，
      相似度分数：Math.min(100, s.score),
      nuanceExplanationAr：细微差别，
      匹配方面：s.aspect，
    };
  });

  常量总计 = 得分。长度；
  const pagination = Scored.slice(offset, offset + limit).map(s => s.item);

  返回{
